using System.Text;
using System.Text.Json;
using ProjectRpg.Backend.Api;
using ProjectRpg.Backend.Data;
using ProjectRpg.Backend.Domain;
using ProjectRpg.Backend.Domain.Trading;

// Contract fixture generated by actual repositories and the production HTTP mapper, never hand-copied JSON.
internal static class AuctionWireFixtures
{
    private sealed class Clock : TimeProvider
    { public override DateTimeOffset GetUtcNow() => new DateTimeOffset(2026,11,12,0,0,0,TimeSpan.Zero).AddTicks(7); }
    public static async Task<int> Run(string directory)
    {
        if (!Guid.TryParseExact(Environment.GetEnvironmentVariable("PROJECT_RPG_AUCTION_CLIENT_RUN"),"N",out _)) throw new Exception("Owned client fixture run required.");
        string path=Path.GetFullPath(directory);
        if (!path.Contains(Path.DirectorySeparatorChar+"Saved"+Path.DirectorySeparatorChar+"AU"+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)
            && !path.Contains(Path.DirectorySeparatorChar+"Saved"+Path.DirectorySeparatorChar+"AR"+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)
            && !path.Contains(Path.DirectorySeparatorChar+"Saved"+Path.DirectorySeparatorChar+"AA"+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)
            && !path.Contains(Path.DirectorySeparatorChar+"Saved"+Path.DirectorySeparatorChar+"AS"+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)) throw new Exception("Owned fixture output required.");
        Directory.CreateDirectory(path);
        var clock=new Clock();var gate=new InMemoryTransactionGate(clock);var items=new InMemoryItemRepository(gate);var money=new InMemoryEconomyRepository(gate);var game=new InMemoryGameRepository(gate,items,clock);
        var store=new InMemoryAuctionRepository(gate,game,items,money,new([new("Material","Ore",1,true,true,100)]),new(10,500));
        await money.UpsertDefinitionAsync(new("Gold","Gold",CurrencyScope.Account,long.MaxValue,true),clock.GetUtcNow(),default);
        async Task<TradeParticipant> Person(string account)
        {await game.UpsertAccountAsync(new(account,account,false,false),clock.GetUtcNow(),default);var c=await game.CreateCharacterAsync(account,"Wire"+account[^4..],clock.GetUtcNow(),default);return new(account,c.CharacterId);}
        var seller=await Person("76561198880000001");var buyer=await Person("76561198880000002");
        var owner=new ItemOwnerRef(ItemOwnerType.Character,seller.CharacterId.ToString("D"));
        var raw=new ItemRecord("Material","Ore",1,owner,new(ItemContainerType.Inventory,owner.OwnerId,160),new(Guid.NewGuid(),17,10,["Item.Ore"],[new("Stat.Value",4.5)]),0,ItemLifecycleState.Active,new(ItemBindState.Unbound,new(0,0),null,"WireFixture",false));
        var seed=await items.CommitAsync(new(Guid.NewGuid(),"Test.Seed","wire",owner,10,[new(0,raw)]),clock.GetUtcNow(),default);
        if(seed.Status!=ItemRepositoryCommitStatus.Committed)throw new Exception("Wire seed failed");
        var terms=new AuctionTerms("Gold",1,long.MaxValue,TimeSpan.FromSeconds(1),TimeSpan.FromDays(7),333);
        var registration=new AuctionEscrowCommand(Guid.NewGuid(),Guid.NewGuid(),seller,AuctionEscrowKind.Register,Item:new(raw.ItemId,1,4),TotalPrice:long.MaxValue,ExpiresAt:clock.GetUtcNow().AddHours(1),Terms:terms);
        var registered=await store.ExecuteAsync(registration,default);
        async Task Write(string name,object value)=>await File.WriteAllTextAsync(Path.Combine(path,name+".json"),JsonSerializer.Serialize(value,new JsonSerializerOptions(JsonSerializerDefaults.Web)),new UTF8Encoding(false));
        await Write("listing",AuctionApiContracts.Listing(registered.Listing,false));await Write("own",AuctionApiContracts.Listing(registered.Listing,true));
        var second=registration with {RequestId=Guid.NewGuid(),ListingId=Guid.NewGuid(),Item=new(raw.ItemId,2,1),TotalPrice=699};
        var secondListing=await store.ExecuteAsync(second,default);await Write("cancelOwn",AuctionApiContracts.Listing(secondListing.Listing,true));
        await Write("page",AuctionApiContracts.Page(await store.SearchAsync(new(1),null,default),false));
        await Write("registration",AuctionApiContracts.Result(registered));
        var funding=await money.CommitAsync(new(Guid.NewGuid(),buyer.CharacterId,Guid.NewGuid(),"Test.Fund","wire","test",[new("Gold",long.MaxValue)]),(await game.GetCharacterEconomyContextAsync(buyer.CharacterId,default))!,clock.GetUtcNow(),default);
        if(funding.Status!=CurrencyTransactionStatus.Committed)throw new Exception("Wire fund failed");
        var purchase=await store.PurchaseAsync(new(Guid.NewGuid(),registration.ListingId,buyer,1,"Gold",long.MaxValue),default);
        await Write("purchase",AuctionApiContracts.Result(purchase));await Write("sold",AuctionApiContracts.Listing(purchase.Listing,true));
        var payable=(await store.FindPayableAsync(registration.ListingId,seller,default))!;await Write("payable",AuctionApiContracts.Payable(payable));
        var claim=await store.ClaimAsync(new(Guid.NewGuid(),registration.ListingId,seller,1,"Gold",200),default);await Write("claim",AuctionApiContracts.Result(claim));
        await Write("payableAfter",AuctionApiContracts.Payable(claim.Payable));
        var full=await money.CommitAsync(new(Guid.NewGuid(),seller.CharacterId,Guid.NewGuid(),"Test.Fund","full","test",[new("Gold",long.MaxValue-200)]),(await game.GetCharacterEconomyContextAsync(seller.CharacterId,default))!,clock.GetUtcNow(),default);
        if(full.Status!=CurrencyTransactionStatus.Committed)throw new Exception("Wire full wallet failed");
        await Write("claimZero",AuctionApiContracts.Result(await store.ClaimAsync(new(Guid.NewGuid(),registration.ListingId,seller,2,"Gold",1),default)));
        var cancelled=await store.ExecuteAsync(new(Guid.NewGuid(),second.ListingId,seller,AuctionEscrowKind.Cancel,1),default);await Write("cancel",AuctionApiContracts.Result(cancelled));
        await Write("identity",new{sellerCharacterId=seller.CharacterId,buyerCharacterId=buyer.CharacterId,itemId=raw.ItemId,initialItemRevision="1"});
        if (Guid.TryParseExact(Environment.GetEnvironmentVariable("PROJECT_RPG_AUCTION_ASSETS_RUN"),"N",out _))
        {
            var a=(await store.AssetsAsync(purchase.RequestId,buyer,default))!;
            await Write("assets",AuctionApiContracts.Assets(a));
        }
        Console.WriteLine("PASS Auction wire fixtures: JSON documents from actual Memory commits/query and production API mapper; no HTTP/UE claim.");return 0;
    }
}
